  result.putString("stream","OLDI_UPGRADE_PASS: top/bottom navigation, direct settings, 21 themes with neon, honest generator-disabled state, explicit photo consent, async generated-frame transport and animated decode (synthetic provider fixture, live AI not tested), visible result, reopen/resume of same job, save confirmation Yes/No, permanent account-owned collection and no provider branding, long-press selection, microphone hold and slide-to-cancel\n");finish(-1,result);
